#!/usr/bin/env python3
import cyclopts
from pathlib import Path
import sys

try:
    import tomllib
except ImportError:
    import tomli as tomllib


def load_config() -> dict:
    """Load [tool.mycli] from pyproject.toml in current directory."""
    config_file = Path.cwd() / "pyproject.toml"
    if not config_file.exists():
        return {}

    with open(config_file, "rb") as f:
        data = tomllib.load(f)

    return data.get("tool", {}).get("mycli", {})


# Load configuration at module initialization
_config = load_config()

# Create CLI app with TOML-based defaults
app = cyclopts.App()


@app.default
def main(
    name: str = _config.get("name", "World"),
    count: int = _config.get("count", 1),
    verbose: bool = _config.get("verbose", False),
) -> None:
    """
    Greet someone with configurable options.

    Configuration can be set in [tool.mycli] section of pyproject.toml:
        [tool.mycli]
        name = "Alice"
        count = 3
        verbose = true

    Command-line arguments override configuration file values.
    """
    for _ in range(count):
        message = f"Hello, {name}!"
        if verbose:
            print(f"[VERBOSE] {message}")
        else:
            print(message)


if __name__ == "__main__":
    app()

